<?php include __DIR__.'/start.php';?><section><p class="eyebrow"><?=me(__('manor.management'))?></p><h1><?=me(__('manor.wonham_console'))?></h1><div class="admin-dashboard-links"><?php foreach(\App\Manor\SettingsController::SECTIONS as $section):if($section==='setup'&&$settings['setup_complete'])continue;?><a class="panel" href="/admin/manor/settings/<?=$section?>"><?=me(__('manor.settings_'.$section))?></a><?php endforeach?><?php if($settings['flags']['invitations']):?><a class="panel" href="/admin/manor/guests"><?=me(__('manor.invitations_attendance'))?></a><?php endif?></div><h2><?=me(__('manor.booking_requests'))?></h2><div class="table-scroll"><table><tr><th><?=me(__('manor.reference'))?></th><th><?=me(__('manor.venue'))?></th><th><?=me(__('manor.start_london'))?></th><th><?=me(__('manor.status'))?></th></tr><?php foreach($records as $record):?><tr><td><a href="?id=<?=me($record['id'])?>"><?=me($record['id'])?></a></td><td><?=me($record['unit_name'])?></td><td><?=me(\App\Manor\Inventory::local($record['starts_at']))?></td><td><?=me(__('manor.status_'.$record['status']))?></td></tr><?php endforeach?></table></div><h2><?=me(__('manor.active_inventory_blocks'))?></h2><?php foreach($blocks as $block):?><form method="post"><?=csrf()?><input type="hidden" name="action" value="unblock"><input type="hidden" name="block_id" value="<?=me($block['request_id'])?>"><p><strong><?=me($block['resource_names'])?></strong><br><?=me(\App\Manor\Inventory::local($block['starts_at']).' — '.\App\Manor\Inventory::local($block['ends_at']))?> · Europe/London</p><button><?=me(__('manor.release_block'))?></button></form><?php endforeach?><details><summary><?=me(__('manor.block_inventory'))?></summary><form method="post"><?=csrf()?><input type="hidden" name="action" value="block"><label><?=me(__('manor.venue'))?><select name="unit_id"><?php foreach($units as $unit):?><option value="<?=me($unit['id'])?>"><?=me($unit['name'])?></option><?php endforeach?></select></label><?=field('start',__('manor.start_london'),'','datetime-local')?><?=field('end',__('manor.end_london'),'','datetime-local')?><input type="hidden" name="guests" value="1"><button><?=me(__('manor.block_inventory'))?></button></form></details><h2><?=me(__('manor.contact_newsletter_inbox'))?></h2><?php foreach($messages as $message):$data=json_decode($message['data'],true);?><article class="panel"><p><?=me($message['kind'].' · '.$message['created_at'])?></p><p><?=me($data['email']??'')?></p><p><?=nl2br(me($data['message']??''))?></p></article><?php endforeach?></section><?php include __DIR__.'/end.php';?>
